.reset-clock { position: absolute; top: var(--corner-row-top); left: var(--reset-clock-left); width: var(--reset-clock-width); height: var(--reset-help-size); }
.reset-clock[hidden], .reset-clock__list[hidden] { display: none; }
.overlay:has(.panel__titlebar > .guide-help:not([hidden]):not([hidden] *)) .reset-clock { display: none; }
.reset-clock__button { box-sizing: border-box; display: grid; place-items: center; width: 100%; height: 100%; padding: 0px; cursor: pointer; }
.reset-clock__icon { width: calc(var(--reset-help-size) - 12px); height: calc(var(--reset-help-size) - 12px); }
.reset-clock__list { box-sizing: border-box; position: fixed; top: var(--corner-list-top); left: var(--corner-row-left); z-index: var(--z-popup); display: flex; flex-direction: column; gap: var(--space-1); width: min(320px, calc(100vw - 2 * (var(--hud-inset) + var(--space-2)))); max-height: calc(100dvh - var(--corner-list-top) - var(--space-2)); overflow-y: auto; overscroll-behavior: contain; padding: var(--space-2) var(--space-3); border: 1px solid var(--colour-border); border-radius: var(--radius-md); background: var(--colour-surface-raised); backdrop-filter: var(--blur-panel); box-shadow: var(--shadow-popup); color: var(--colour-text); font-size: var(--text-sm); line-height: 1.3; }
.reset-clock__heading { margin: 0px; color: var(--colour-text-strong); font-family: var(--font-display); font-size: var(--text-md); }
.reset-clock__rows { display: flex; flex-direction: column; gap: var(--space-1); margin: 0px; padding: 0px; list-style: none; }
.reset-clock__row { display: flex; align-items: baseline; justify-content: space-between; gap: var(--space-3); }
.reset-clock__name { display: flex; flex-direction: column; min-width: 0px; }
.reset-clock__title { color: var(--colour-text-strong); font-weight: 700; }
.reset-clock__detail { color: var(--colour-text-muted); font-size: 12px; }
.reset-clock__left { flex: 0 0 auto; color: var(--colour-warning-bright); font-weight: 700; font-variant-numeric: tabular-nums; white-space: nowrap; }
.overlay__layer:has(> .reset-clock:not([hidden])) > .hud--corner > .hud-status.hud-status { position: fixed; top: var(--corner-row-top); left: calc(var(--reset-clock-left) + var(--reset-clock-width) + var(--space-2)); max-width: none; }
@media (min-width: 621px) and (max-height: 500px) {
  .overlay__layer:has(> .reset-clock:not([hidden])) > .hud--corner > .hud-status.hud-status { left: calc(226px + var(--events-door-side-width) + var(--space-2)); }
}

.guide-help { font-family: var(--font-body); font-weight: 700; }
.guide-help[hidden] { display: none; }
.btn--icon.guide-help { font-size: var(--text-md); }
.panel__titlebar > .guide-help { margin-left: auto; }
.panel__titlebar > .guide-help ~ button[aria-label^="Close"] { margin-left: 0px; }
.guide-help--float { position: fixed; top: calc(var(--hud-height) + var(--space-2)); left: calc(var(--hud-inset) + var(--space-2)); width: 32px; height: 32px; padding: 0px; }
:is(.guide-help--float, .reset-clock__button) { border: 2px solid var(--guide-bubble-line); border-radius: 50%; background: var(--guide-bubble); color: var(--guide-bubble-text); box-shadow: var(--shadow-bubble-drop); font-size: var(--text-md); line-height: 1; cursor: pointer; pointer-events: auto; }
.overlay:has(.panel__titlebar > .guide-help:not([hidden]):not([hidden] *)) .guide-help--float { display: none; }
:is(.guide-help--float, .reset-clock__button):hover { filter: brightness(1.06); }
:is(.guide-help--float, .reset-clock__button):focus-visible { outline: 2px solid var(--guide-ring); outline-offset: 2px; }
@media (pointer: coarse) {
  .guide-help--float { width: 40px; height: 40px; }
}
@media (max-width: 620px) {
  .attack-strip > .guide-help { display: none; }
}

.team-notice-popup { width: min(440px, calc(100vw - 2 * var(--space-4))); }
.team-notice { display: flex; flex-direction: column; gap: var(--space-3); }
.team-notice__head { display: flex; align-items: flex-start; gap: var(--space-3); }
.team-notice__badge { flex: 0 0 auto; padding: 2px var(--space-2); border-radius: var(--radius-sm); background: var(--colour-success); color: rgb(13, 36, 22); font-size: var(--text-sm); font-weight: 800; letter-spacing: 0.04em; }
.team-notice__text { margin: 0px; font-size: var(--text-md); line-height: var(--leading-normal); color: var(--colour-text-strong); overflow-wrap: anywhere; white-space: pre-line; }
.team-notice__until { margin: 0px; color: var(--colour-text-secondary); font-size: var(--text-sm); }
.team-notice__foot { display: flex; justify-content: flex-end; }
